     1	import { router, Stack } from 'expo-router';
     2	import {
     3	  ActivityIndicator,
     4	  FlatList,
     5	  Pressable,
     6	  RefreshControl,
     7	  StyleSheet,
     8	  Text,
     9	  View,
    10	} from 'react-native';
    11	
    12	import { isApiError } from '@/api/http';
    13	import { useActivity } from '@/api/queries';
    14	import type { ActivityItem, ActivityStatus } from '@/api/types';
    15	import { Colors, MaxContentWidth, Spacing } from '@/constants/theme';
    16	import { formatAmount } from '@/lib/amount';
    17	
    18	const TYPE_LABEL = { accrual: 'Payback', reversal: 'Reversal', claim: 'Claim' } as const;
    19	
    20	const STATUS_COLOR: Record<ActivityStatus, string> = {
    21	  pending: Colors.warning,
    22	  confirmed: Colors.success,
    23	  completed: Colors.success,
    24	  failed: Colors.danger,
    25	};
    26	
    27	const errorMessage = (e: unknown) => (isApiError(e) ? e.message : 'Something went wrong.');
    28	
    29	export default function ActivityScreen() {
    30	  const activity = useActivity();
    31	  const items = activity.data?.pages.flatMap((p) => p.items) ?? [];
    32	  const header = <Stack.Screen options={{ title: 'Activity' }} />;
    33	
    34	  if (activity.isPending) {
    35	    return (
    36	      <View style={styles.center}>
    37	        {header}
    38	        <ActivityIndicator size="large" color={Colors.primary} />
    39	        <Text style={styles.muted}>Loading activity…</Text>
    40	      </View>
    41	    );
    42	  }
    43	
    44	  if (!activity.data) {
    45	    return (
    46	      <View style={styles.center}>
    47	        {header}
    48	        <Text style={styles.errorTitle}>Could not load activity</Text>
    49	        <Text style={styles.muted}>{errorMessage(activity.error)}</Text>
    50	        <RetryButton busy={activity.isFetching} onPress={() => activity.refetch()} />
    51	      </View>
    52	    );
    53	  }
    54	
    55	  const loadMore = () => {
    56	    // isFetching, not isFetchingNextPage: fetchNextPage during a pull-to-refresh would cancel the refetch.
    57	    if (activity.hasNextPage && !activity.isFetching && !activity.isFetchNextPageError) {
    58	      void activity.fetchNextPage();
    59	    }
    60	  };
    61	
    62	  return (
    63	    <FlatList
    64	      style={styles.screen}
    65	      contentContainerStyle={styles.content}
    66	      data={items}
    67	      keyExtractor={(i) => i.id}
    68	      renderItem={({ item }) => <ActivityRow item={item} />}
    69	      ItemSeparatorComponent={() => <View style={styles.separator} />}
    70	      onEndReached={loadMore}
    71	      onEndReachedThreshold={0.5}
    72	      refreshControl={
    73	        <RefreshControl
    74	          refreshing={activity.isRefetching && !activity.isFetchingNextPage}
    75	          onRefresh={() => void activity.refetch()}
    76	          tintColor={Colors.primary}
    77	        />
    78	      }
    79	      ListHeaderComponent={
    80	        <>
    81	          {header}
    82	          {activity.isRefetchError && (
    83	            <View style={styles.banner} accessibilityRole="alert">
    84	              <Text style={styles.bannerText}>
    85	                Couldn&apos;t refresh, showing older data. {errorMessage(activity.error)}
    86	              </Text>
    87	            </View>
    88	          )}
    89	        </>
    90	      }
    91	      ListEmptyComponent={<Text style={[styles.muted, styles.footer]}>No activity yet.</Text>}
    92	      ListFooterComponent={
    93	        items.length === 0 ? undefined : activity.isFetchingNextPage ? (
    94	          <ActivityIndicator style={styles.footer} color={Colors.primary} />
    95	        ) : activity.isFetchNextPageError ? (
    96	          <View style={styles.footer}>
    97	            <Text style={styles.bannerText}>{errorMessage(activity.error)}</Text>
    98	            <RetryButton busy={false} onPress={() => activity.fetchNextPage()} />
    99	          </View>
   100	        ) : activity.hasNextPage ? (
   101	          // Fallback when onEndReached doesn't fire (e.g. short list on a tall web window).
   102	          <Pressable accessibilityRole="button" onPress={loadMore} style={styles.footer}>
   103	            <Text style={styles.link}>Load more</Text>
   104	          </Pressable>
   105	        ) : (
   106	          <Text style={[styles.muted, styles.footer]}>That&apos;s everything.</Text>
   107	        )
   108	      }
   109	    />
   110	  );
   111	}
   112	
   113	function ActivityRow({ item }: { item: ActivityItem }) {
   114	  // No decimals in activity items: show the server string's own precision.
   115	  const decimals = item.amount.split('.')[1]?.length ?? 0;
   116	  const negative = item.amount.startsWith('-');
   117	  const claimId = item.type === 'claim' ? item.relatedId : null;
   118	  const body = (
   119	    <>
   120	      <View style={styles.row}>
   121	        <Text style={styles.title}>
   122	          {item.exchange ? `${TYPE_LABEL[item.type]} · ${item.exchange}` : TYPE_LABEL[item.type]}
   123	        </Text>
   124	        <Text style={[styles.amount, negative && { color: Colors.danger }]}>
   125	          {negative ? '' : '+'}
   126	          {formatAmount(item.amount, decimals)} {item.asset}
   127	        </Text>
   128	      </View>
   129	      <View style={styles.row}>
   130	        <Text style={styles.muted}>{new Date(item.createdAt).toLocaleString()}</Text>
   131	        <Text style={[styles.badge, { color: STATUS_COLOR[item.status] }]}>{item.status}</Text>
   132	      </View>
   133	    </>
   134	  );
   135	  if (!claimId) return <View style={styles.item}>{body}</View>;
   136	  return (
   137	    <Pressable
   138	      accessibilityRole="button"
   139	      accessibilityHint="Open claim status"
   140	      onPress={() => router.push({ pathname: '/claims/[id]', params: { id: claimId } })}
   141	      style={({ pressed }) => [styles.item, pressed && styles.pressed]}>
   142	      {body}
   143	    </Pressable>
   144	  );
   145	}
   146	
   147	function RetryButton({ busy, onPress }: { busy: boolean; onPress: () => void }) {
   148	  return (
   149	    <Pressable
   150	      accessibilityRole="button"
   151	      onPress={onPress}
   152	      disabled={busy}
   153	      style={[styles.button, busy && styles.disabled]}>
   154	      <Text style={styles.buttonText}>{busy ? 'Retrying…' : 'Retry'}</Text>
   155	    </Pressable>
   156	  );
   157	}
   158	
   159	const styles = StyleSheet.create({
   160	  screen: { flex: 1, backgroundColor: Colors.background },
   161	  content: {
   162	    width: '100%',
   163	    maxWidth: MaxContentWidth,
   164	    alignSelf: 'center',
   165	    padding: Spacing.three,
   166	  },
   167	  center: {
   168	    flex: 1,
   169	    alignItems: 'center',
   170	    justifyContent: 'center',
   171	    gap: Spacing.three,
   172	    padding: Spacing.four,
   173	    backgroundColor: Colors.background,
   174	  },
   175	  item: { paddingVertical: Spacing.three, gap: Spacing.one },
   176	  pressed: { opacity: 0.6 },
   177	  row: { flexDirection: 'row', justifyContent: 'space-between', gap: Spacing.two },
   178	  title: { fontSize: 16, fontWeight: '600', color: Colors.text, flexShrink: 1 },
   179	  amount: { fontSize: 16, fontWeight: '600', color: Colors.text },
   180	  badge: { fontSize: 13, fontWeight: '600', textTransform: 'capitalize' },
   181	  muted: { fontSize: 13, color: Colors.textSecondary },
   182	  separator: { height: StyleSheet.hairlineWidth, backgroundColor: Colors.border },
   183	  footer: { alignItems: 'center', paddingVertical: Spacing.four, gap: Spacing.two, textAlign: 'center' },
   184	  link: { color: Colors.primary, fontSize: 15 },
   185	  banner: { marginBottom: Spacing.two, padding: Spacing.three, borderRadius: 10, backgroundColor: '#FDECEA' },
   186	  bannerText: { color: Colors.danger, fontSize: 14 },
   187	  errorTitle: { fontSize: 18, fontWeight: '600', color: Colors.text },
   188	  button: {
   189	    backgroundColor: Colors.primary,
   190	    borderRadius: 10,
   191	    paddingVertical: 12,
   192	    paddingHorizontal: Spacing.five,
   193	  },
   194	  buttonText: { color: '#FFFFFF', fontSize: 16, fontWeight: '600' },
   195	  disabled: { opacity: 0.5 },
   196	});
